const D = { energy:.6, scale:1, density:.5, speed:1, hue:38, x:.5, y:.56, sway:.5, style:'stone', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height);
const sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, HU = ((P.hue%360)+360)%360;
const wire = (sty === 'blueprint'), paper = (sty === 'engraving'), dark = (sty === 'chiaroscuro');

// ---- walk the hall. ranks keyed on ABSOLUTE index -> translation symmetry broken
if (S.pt == null || K.t < S.pt) S.pt = K.t;
const dt = cl(K.t - S.pt, 0, .1); S.pt = K.t;
S.z = (S.z||0) + dt * P.speed * (.11 + .13*K.intensity + .12*P.energy);
const bsm = (S.bm = (S.bm||0)*.84 + (A.bass||0)*.16);
const gl = (.42 + .58*P.energy) * (.55 + .5*K.intensity) + bsm*.26;

const dA = .55*Math.sin(K.t*.41) + .30*Math.sin(K.t*.97+1.7) + .17*Math.sin(K.t*1.63+.4);
const dB = .50*Math.sin(K.t*.53+2.1) + .32*Math.sin(K.t*1.19+.9) + .20*Math.sin(K.t*2.29+2.6);
const dC = .60*Math.sin(K.t*.089) + .40*Math.sin(K.t*.211+1.1);

// Z pitch fixed so P.scale is NOT a no-op on the projection
const CS = u*.66;
const XS = u*.50*P.scale, CH = u*.95*P.scale, RAD = u*.072*P.scale;
const nx = 4 + 2*Math.round(cl(P.density,0,1)*2);
const NZ = 5 + Math.round(cl(P.density,0,1)*6);
const camZ = S.z*CS;
const camX = XS*.30*dB*cl(P.sway,0,1);
const camY = -(u*.30 + u*.03*dC*P.energy);
const yaw = .06*dA*cl(P.sway,0,1) + .035*Math.sin(K.t*.157+1.9);
const ca = Math.cos(yaw), sa = Math.sin(yaw);
const f = u*1.05, NEAR = u*.10;
const vcx = cl(P.x,.2,.8)*width, vcy = cl(P.y,.3,.8)*height;

// clerestory light: azimuth + the lateral seat of the bright band both crawl slowly
const lam0 = .95*Math.sin(K.t*.047) + .38*Math.sin(K.t*.113+2.2);
const lz0 = S.z + 2.6 + 2.2*Math.sin(K.t*.061) + 1.1*Math.sin(K.t*.149+1.3);

// ---- projection --------------------------------------------------------------
const AX = new Float64Array(10), AY = new Float64Array(10), AZ = new Float64Array(10);
const BX = new Float64Array(14), BY = new Float64Array(14);
function poly(v){
  const n = v.length/3;
  for (let i=0;i<n;i++){
    const X = v[i*3]-camX, Y = v[i*3+1]-camY, Z = v[i*3+2]-camZ;
    AX[i] = X*ca - Z*sa; AY[i] = Y; AZ[i] = X*sa + Z*ca;
  }
  let m = 0;
  for (let i=0;i<n;i++){
    const j = (i+1)%n, az = AZ[i], bz = AZ[j], ai = az>NEAR, bi2 = bz>NEAR;
    if (ai){ BX[m] = vcx + f*AX[i]/az; BY[m] = vcy + f*AY[i]/az; m++; }
    if (ai !== bi2){
      const tt = (NEAR-az)/(bz-az);
      BX[m] = vcx + f*(AX[i]+(AX[j]-AX[i])*tt)/NEAR;
      BY[m] = vcy + f*(AY[i]+(AY[j]-AY[i])*tt)/NEAR; m++;
    }
  }
  if (m < 3) return false;
  beginShape(); for (let i=0;i<m;i++) vertex(BX[i], BY[i]); endShape(CLOSE);
  return true;
}
// pure yaw + no pitch => every vertical world line stays vertical on screen
function axis(X,Z){
  const dx = X-camX, dz = Z-camZ;
  return [dx*ca - dz*sa, dx*sa + dz*ca];
}

// ---- tone tables -------------------------------------------------------------
function mixc(c,d,t){ const dh = ((d[0]-c[0])%360+540)%360-180;
  return [c[0]+dh*t, c[1]+(d[1]-c[1])*t, c[2]+(d[2]-c[2])*t]; }
const HAZE = paper ? [40, 7, 92] : wire ? [212, 58, 22] : dark ? [HU, 16, 9]
           : sty === 'lapis' ? [224, 52, 30] : [(HU+6)%360, 26, 40];
const fogA = (paper||wire) ? .30 : .78;
// v: 0..1 modelled luminance -> a colour in the current discipline
function tone(v, tv){
  if (paper) return [40, 6 + 4*tv, cl(97 - 52*(1-v), 40, 97)];
  if (wire)  return [212, 60, cl(12 + 10*v, 8, 30)];
  if (dark)  return [HU, cl(24 - 14*v, 0, 30), cl(2 + 88*Math.pow(v,1.9), 1, 96)];
  if (sty === 'lapis') return [cl(228 - 26*v, 190, 240), cl(66 - 26*v, 12, 80), cl(10 + 72*v, 6, 92)];
  return [(HU + 8 - 6*v)%360, cl(30 - 12*v + 6*tv, 4, 44), cl(9 + 70*v, 5, 94)];
}
function ink(a){
  if (wire) stroke(190, 30, 100, a);
  else if (paper) stroke(30, 20, 14, a);
  else stroke((HU+10)%360, 14, 84, a*.3);
}

// ---- ceiling gloom + floor (banded, cached-free but only ~64 rects) ----------
noStroke();
const NBD = 30;
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1);
  const c = tone(.03 + .12*(1-s)*(dark?.4:1), fr(i*3.1));
  fill(c[0], c[1], cl(c[2] + (fr(i*5.7)-.5)*1.5, 0, 100));
  rect(0, s*vcy - 1.5, width, vcy/NBD + 3);
}
for (let i=0;i<NBD;i++){
  const s = i/(NBD-1);
  const c = tone(.18 + .24*s, fr(i*7.7+11));
  fill(c[0], c[1]*.9, cl(c[2] + (fr(i*9.1+3)-.5)*2.2, 0, 100));
  rect(0, vcy + s*(height-vcy) - 1.5, width, (height-vcy)/NBD + 3);
}

// ---- floor slab joints receding to the vanishing point ------------------------
strokeWeight(Math.max(1, u*.0013));
ink(paper ? 30 : 34); noFill();
for (let j=Math.floor(S.z); j<S.z+NZ+2; j++){
  poly([-XS*(nx+1)*.5, 0, j*CS, XS*(nx+1)*.5, 0, j*CS]);
}
for (let i=0;i<=nx;i++){
  const X = (i - (nx-1)/2 - .5)*XS;
  poly([X, 0, Math.floor(S.z)*CS, X, 0, (S.z+NZ+2)*CS]);
}

// ---- pooled clerestory light on the floor (partial frame, ADD, never a flash) -
if (!paper && !wire){
  push(); blendMode(ADD); noStroke();
  for (let i=0;i<3;i++){
    const zz = (lz0 + i*1.9 - 1.9)*CS;
    fill(sty==='lapis'?196:(HU+4)%360, 30, 100, 3.0 + 5.2*gl);
    poly([-XS*nx*.6, 0, zz, XS*nx*.6, 0, zz, XS*nx*.6, 0, zz+CS*.42, -XS*nx*.6, 0, zz+CS*.42]);
  }
  pop(); blendMode(BLEND);
}

// ---- architraves: beams running down each rank of columns ---------------------
const zA = Math.floor(S.z)*CS, zB = (S.z+NZ+1)*CS, BH = u*.15*P.scale;
for (let i=0;i<nx;i++){
  const X = (i - (nx-1)/2)*XS;
  const sgn = (X - camX) >= 0 ? -1 : 1;   // show the beam face that turns toward us
  const bw = RAD*1.15;
  const c = tone(.20 + .16*fr(i*13.3), fr(i*4.1));
  if (wire){ noFill(); ink(60); } else { noStroke(); fill(c[0], c[1], c[2], 100); }
  poly([X+sgn*bw, -CH, zA, X+sgn*bw, -CH-BH, zA, X+sgn*bw, -CH-BH, zB, X+sgn*bw, -CH, zB]);
  const c2 = tone(.06 + .06*fr(i*9.7), fr(i*2.3));
  if (!wire){ noStroke(); fill(c2[0], c2[1], c2[2], 100); }
  poly([X-bw, -CH, zA, X+bw, -CH, zA, X+bw, -CH, zB, X-bw, -CH, zB]);
}

// ---- columns: gather, depth-sort, paint far -> near ---------------------------
const cols = [];
for (let i=0;i<nx;i++){
  for (let j=Math.floor(S.z); j<S.z+NZ; j++){
    const X = (i - (nx-1)/2)*XS, Z = j*CS;
    const a2 = axis(X, Z);
    if (a2[1] <= NEAR*1.4) continue;
    const sx = vcx + f*a2[0]/a2[1];
    const rw = f*RAD/a2[1];
    if (sx + rw < -u*.05 || sx - rw > width + u*.05) continue;
    cols.push([a2[1], sx, rw, i, j]);
  }
}
cols.sort((a,b) => b[0]-a[0]);

const NC = Math.min(cols.length, 58);
for (let q = cols.length-NC; q < cols.length; q++){
  const cd = cols[q], zc = cd[0], sx = cd[1], rw = cd[2], ci = cd[3], cj = cd[4];
  const hz = cl((zc - NEAR)/(NZ*CS*.9), 0, 1);
  const yb = vcy + f*(0 - camY)/zc;              // shaft foot
  const yt = vcy + f*(-CH - camY)/zc;            // shaft head
  const tv = fr(ci*31.7 + cj*5.3);               // seeded weathering, absolute index
  const litz = cl(1.05 - Math.abs(cj - lz0)*.30, .34, 1);
  const NS = cl(Math.round(rw/(u*.009)), 1, 9);  // flutes only where they'd read

  // shaft — fluted, never a flat fill
  for (let s2=0; s2<NS; s2++){
    const p0 = -1 + 2*s2/NS, p1 = -1 + 2*(s2+1)/NS, pm = (p0+p1)*.5;
    const lamb = cl(.14 + .92*Math.cos((pm - lam0*.72)*1.32), 0, 1);
    const flute = .58 + .42*Math.cos(pm*Math.PI*3.4);
    let v = lamb*(.60+.40*flute)*litz*(.55+.55*gl)*(.92+.16*tv);
    v = cl(v*(1 - .18*hz) + .05, 0, 1);
    const c = mixc(tone(v, tv), HAZE, hz*fogA);
    if (wire){ noFill(); ink(52); }
    else { noStroke(); fill(c[0], c[1], c[2], 100); }
    rect(sx + p0*rw, yt, (p1-p0)*rw + 1.1, yb-yt);
  }
  // drum joints — horizontal banding across the shaft
  if (NS > 3 && !wire){
    noStroke();
    for (let d2=1; d2<6; d2++){
      const yy = yt + (yb-yt)*(d2/6 + .04*(fr(cj*7.1+d2)-.5));
      const c = mixc(tone(cl(.10 + .22*litz, 0, 1), tv), HAZE, hz*fogA);
      fill(c[0], c[1], c[2], paper ? 44 : 66);
      rect(sx - rw, yy, rw*2, Math.max(1, rw*.045));
    }
  }
  // base torus + capital + abacus
  const capV = cl(.30 + .62*litz*(.5+.5*gl), 0, 1);
  const cc = mixc(tone(capV, tv), HAZE, hz*fogA);
  if (wire){ noFill(); ink(64); } else { noStroke(); fill(cc[0], cc[1], cc[2], 100); }
  const ch2 = (yb-yt)*.055 + 1;
  rect(sx - rw*1.24, yt, rw*2.48, ch2*1.6);                       // capital flare
  rect(sx - rw*1.40, yt - ch2*.75, rw*2.80, ch2*.85);             // abacus
  const bc = mixc(tone(cl(capV*.55+.06,0,1), tv), HAZE, hz*fogA);
  if (!wire){ noStroke(); fill(bc[0], bc[1], bc[2], 100); }
  rect(sx - rw*1.22, yb - ch2*1.1, rw*2.44, ch2*1.1);             // base

  // engraved hatching on the dark side of near shafts
  if (paper && rw > u*.02){
    ink(38); strokeWeight(Math.max(1, u*.0011));
    const nh = Math.round(cl(rw/(u*.006), 2, 9));
    for (let s2=0; s2<nh; s2++){
      const pm = -1 + 2*(s2+.5)/nh;
      const lamb = cl(.14 + .92*Math.cos((pm - lam0*.72)*1.32), 0, 1);
      if (lamb > .42) continue;
      const xx = sx + pm*rw;
      line(xx, yt + ch2*1.6, xx, yb - ch2*1.1);
    }
  }
}

// ---- shafts of haze between the ranks (partial, low alpha) --------------------
if (!paper && !wire){
  push(); blendMode(ADD); noStroke();
  for (let i=0;i<3;i++){
    const zz = (lz0 + i*1.9 - 1.9)*CS;
    const a2 = axis(0, zz);
    if (a2[1] <= NEAR*1.4) continue;
    const sxx = vcx + f*a2[0]/a2[1];
    const ww = f*XS*nx*.5/a2[1];
    for (let r2=3; r2>=1; r2--){
      fill(sty==='lapis'?200:(HU+2)%360, 24, 100, 1.6 + 2.6*gl);
      quad(sxx - ww*.12*r2, vcy + f*(-CH-camY)/a2[1], sxx + ww*.12*r2, vcy + f*(-CH-camY)/a2[1],
           sxx + ww*.34*r2, vcy + f*(0-camY)/a2[1], sxx - ww*.34*r2, vcy + f*(0-camY)/a2[1]);
    }
  }
  pop(); blendMode(BLEND);
}

// ---- cached grain + vignette --------------------------------------------------
if (!S.gv || S.gk !== width+'x'+height+'|'+sty){
  const g = createGraphics(width, height); g.colorMode(HSB,360,100,100,100); g.noStroke();
  const N = Math.min(9000, Math.floor(width*height/230));
  for (let i=0;i<N;i++){
    const px = Math.abs((Math.sin(i*12.9898)*43758.5453)%1)*width;
    const py = Math.abs((Math.sin(i*78.233+2.1)*43758.5453)%1)*height;
    g.fill(0,0, (i%2) ? 100 : 0, paper ? 8 : 5);
    g.rect(px, py, 1.7, 1.7);
  }
  for (let i=0;i<26;i++){ const s=i/26, bw=(1-s)*.09;
    g.fill(0,0,0, 1.1 + 3.8*s*s);
    g.rect(0,0,width,height*bw); g.rect(0,height*(1-bw),width,height*bw);
    g.rect(0,0,width*bw,height); g.rect(width*(1-bw),0,width*bw,height);
  }
  S.gv = g; S.gk = width+'x'+height+'|'+sty;
}
image(S.gv, 0, 0);
if (P.alpha < 100){ noStroke(); fill(0,0,0, cl(100-P.alpha,0,100)); rect(0,0,width,height); }
blendMode(BLEND); drawingContext.shadowBlur = 0; strokeWeight(1);
